WITH joined AS (SELECT src.*, c.segment, c.email, c.age FROM subscriptions src LEFT JOIN customers c ON src.customer_id = c.id), latest AS (SELECT *, RANK() OVER (PARTITION BY plan ORDER BY monthly_fee DESC) AS dedup_rank FROM joined QUALIFY dedup_rank = 1), remaining_keys AS (SELECT plan, id FROM latest INTERSECT ALL SELECT plan, id FROM subscriptions WHERE plan != 'premium'), reconciled AS (SELECT s.* FROM latest s INNER JOIN remaining_keys k ON s.plan = k.plan AND s.id = k.id) SELECT s.id, s.customer_id, s.plan, s.end_date, s.monthly_fee, s.status, s.segment, s.email, s.age, (SELECT SUM(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_amount FROM reconciled s ORDER BY end_date, sum_order_amount
